+}
+
+func requireMCPQuery(query string) error {
+	if strings.TrimSpace(query) == "" {
+		return errors.New("query is required")
+	}
+	return nil
+}
+
+func mcpString(args map[string]any, key string) string {
+	if value, ok := args[key].(string); ok {
